static int child(HANDLE other,int set){WCHAR c1=0,c2=0;DWORD n=0,got=0,waiting=0; INPUT_RECORD r; HANDLE con=CreateFileW(L"CONOUT$",GENERIC_READ|GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,0,NULL);HANDLE in=CreateFileW(L"CONIN$",GENERIC_READ|GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,0,NULL);if(con==INVALID_HANDLE_VALUE||in==INVALID_HANDLE_VALUE)return 20;BOOL r1=ReadConsoleOutputCharacterW(con,&c1,1,(COORD){0,0},&n)&&n==1;BOOL r2=ReadConsoleOutputCharacterW(other,&c2,1,(COORD){0,0},&n)&&n==1;output("child-buffers",r1,c1,r2,c2);output("child-pages-before",GetConsoleCP(),GetConsoleOutputCP(),0,0);if(set){BOOL a=SetConsoleCP(850),b=SetConsoleOutputCP(850);output("child-set",a,b,GetConsoleCP(),GetConsoleOutputCP());if(!a||!b)return 21;if(!GetNumberOfConsoleInputEvents(in,&waiting)||!waiting||!ReadConsoleInputW(in,&r,1,&got))return 22;output("child-input",waiting,got,r.EventType,r.Event.KeyEvent.uChar.UnicodeChar);}CloseHandle(con);CloseHandle(in);return r1&&r2&&c1=='A'&&c2=='B'?0:23;}
static int launch(HANDLE inactive,int set){char image[32768],cmd[33000];STARTUPINFOA si={sizeof si};PROCESS_INFORMATION pi={0};DWORD code;if(!GetModuleFileNameA(NULL,image,sizeof image))return 30;snprintf(cmd,sizeof cmd,"\"%s\" child %llu %d \"%s\"",image,(unsigned long long)(uintptr_t)inactive,set,out);if(!CreateProcessA(image,cmd,NULL,NULL,TRUE,0,NULL,NULL,&si,&pi)){output("launch-error",GetLastError(),0,0,0);return 31;}CloseHandle(pi.hThread);if(WaitForSingleObject(pi.hProcess,INFINITE)!=WAIT_OBJECT_0||!GetExitCodeProcess(pi.hProcess,&code))return 32;CloseHandle(pi.hProcess);output("child-exit",code,0,0,0);return (int)code;}
int main(int argc,char **argv){if(argc>=5&&!strcmp(argv[1],"child")){out=argv[4];return child((HANDLE)(uintptr_t)_strtoui64(argv[2],0,10),atoi(argv[3]));}if(argc!=2)return 40;out=argv[1];if(!FreeConsole()&&GetLastError()!=ERROR_INVALID_HANDLE)return 41;if(!AllocConsole())return 42;ShowWindow(GetConsoleWindow(),SW_HIDE);HANDLE active=CreateFileW(L"CONOUT$",GENERIC_READ|GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,0,NULL),input=CreateFileW(L"CONIN$",GENERIC_READ|GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,0,NULL);SECURITY_ATTRIBUTES sa={sizeof sa,NULL,TRUE};HANDLE other=CreateConsoleScreenBuffer(GENERIC_READ|GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,&sa,CONSOLE_TEXTMODE_BUFFER,NULL);if(active==INVALID_HANDLE_VALUE||input==INVALID_HANDLE_VALUE||other==INVALID_HANDLE_VALUE)return 43;DWORD n,count; if(!WriteConsoleOutputCharacterW(active,L"A",1,(COORD){0,0},&n)||!WriteConsoleOutputCharacterW(other,L"B",1,(COORD){0,0},&n))return 44; if(!SetConsoleCP(437)||!SetConsoleOutputCP(437)||!FlushConsoleInputBuffer(input))return 45;INPUT_RECORD record={0};record.EventType=KEY_EVENT;record.Event.KeyEvent.bKeyDown=TRUE;record.Event.KeyEvent.wRepeatCount=1;record.Event.KeyEvent.wVirtualKeyCode='Q';record.Event.KeyEvent.uChar.UnicodeChar='Q';if(!WriteConsoleInputW(input,&record,1,&n)||n!=1)return 46;output("parent-before",GetConsoleCP(),GetConsoleOutputCP(),0,0);int result=launch(other,1);if(result)return result;if(!GetNumberOfConsoleInputEvents(input,&count))return 47;output("parent-after-child",GetConsoleCP(),GetConsoleOutputCP(),count,0);if(GetConsoleCP()!=850||GetConsoleOutputCP()!=850||count)return 48;if(!SetConsoleCP(437)||!SetConsoleOutputCP(437))return 49;result=launch(other,0);if(result)return result;output("parent-after-reset",GetConsoleCP(),GetConsoleOutputCP(),0,0);CloseHandle(other);CloseHandle(input);CloseHandle(active);FreeConsole();return 0;}
